import { MakeLogicType, kea } from 'kea'

import { Dashboard } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface counterLogicValues {
    counter: number
    dashboard: Dashboard | null
    doubleCounter: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface counterLogicActions {
    increment: (amount: number) => {
        amount: number
    }
    setDashboard: (dashboard: Dashboard) => {
        dashboard: Dashboard
    }
}

export type counterLogicType = MakeLogicType<counterLogicValues, counterLogicActions>

export const counterLogic = kea<counterLogicType>({
    path: ['counterLogic'],
    actions: {
        increment: (amount: number) => ({ amount }),
        setDashboard: (dashboard: Dashboard) => ({ dashboard }),
    },
    reducers: {
        counter: [0, { increment: (state, { amount }) => state + amount }],
        dashboard: [null as Dashboard | null, { setDashboard: (_, { dashboard }) => dashboard }],
    },
    selectors: {
        doubleCounter: [(s) => [s.counter], (counter: number) => counter * 2],
    },
})
